window.ZEN_IS_READY = p => p.category !== 'Add-ons' && !p.name.startsWith('Activity Book Series');
window.ZEN_READY_PRICE = text => {
  const clean = String(text).trim();
  if (!/^(?:J\$|\$)?\s*\d[\d,]*(?:\.\d{1,2})?$/.test(clean)) return null;
  const value = Number(clean.replace(/[^\d.]/g, ''));
  return Number.isFinite(value) && value >= 0 ? value : null;
};
